}

test_krautbereich_und_baumpflege if {
	p := streifen({"herb_permanently_green": true, "herb_use": "Pflegemahd ohne Abtransport", "planting_date": "2026-05-15", "mfa_use": "LSE Agroforststreifen"})
	befunde(p) == set()
